/// <summary>
/// Handles ISM telemetry events from the SysIntParameters form.
/// </summary>
internal final class ISMTelemetryEventHandler
{



}

Method.Source:
/// <summary>
/// Initializes the telemetry parameter setups.
/// </summary>
/// <param name="sender">sender</param>
/// <param name="e">event arguments</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter required by the event interface.'),
FormEventHandler(formStr(SysIntParameters), FormEventType::Initializing)]
public static void sysIntParameters_OnInitializing(xFormRun sender, FormEventArgs e)
{
    ISMTelemetryParameterSetup::initializeParameterSetups(ISMTelemetryMode::Triggered);
    ISMTelemetryParameterSetup::initializeParameterSetups(ISMTelemetryMode::Batchable);
}

/// <summary>
/// Opens the triggered telemetry configuration dialog for the selected telemetry parameter setup.
/// </summary>
/// <param name="sender">The sender of the event.</param>
/// <param name="e">Event arguments associated with the event.</param>
[
    SuppressBPWarning('BPParameterNotUsed', 'Parameter required by the event interface.'),
    FormControlEventHandler(
        formControlStr(SysIntParameters, ISMTriggeredTelemetryConfiguration), 
        FormControlEventType::Clicked)
]
public static void ISMTriggeredTelemetryConfiguration_OnClicked(
    FormControl sender, 
    FormControlEventArgs e)
{
    FormRun formRun = sender.formRun();
    FormDataSource formDataSource = 
        formRun.dataSource(formDataSourceStr(SysIntParameters, ISMTelemetryParameterSetupTriggerable));
    ISMTelemetryEventHandler::manageTelemetryConfiguratin(formDataSource);
}

/// <summary>
/// Opens the batchable telemetry configuration dialog for the selected telemetry parameter setup.
/// </summary>
/// <param name="sender">The sender of the event.</param>
/// <param name="e">Event arguments associated with the event.</param>
[
    SuppressBPWarning('BPParameterNotUsed', 'Parameter required by the event interface.'),
    FormControlEventHandler(
        formControlStr(SysIntParameters, ISMBatchableTelemetryConfiguration),
        FormControlEventType::Clicked)
]
public static void ISMBatchableTelemetryConfiguration_OnClicked(
    FormControl sender,
    FormControlEventArgs e)
{
    FormRun formRun = sender.formRun();
    FormDataSource formDataSource =
        formRun.dataSource(formDataSourceStr(SysIntParameters, ISMTelemetryParameterSetupBatchable));
    ISMTelemetryEventHandler::manageTelemetryConfiguratin(formDataSource);
}

private static void manageTelemetryConfiguratin(FormDataSource _formDataSource)
{
    ISMTelemetryParameterSetup telemetryParameterSetup = _formDataSource.cursor();
    DictClass dictClass = new DictClass(className2Id(telemetryParameterSetup.TelemetryClass));
    ISMTelemetryBase telemetry = dictClass.makeObject();
    if (ISMTelemetryConfigurationDialogController::telemetryConfigurationDialog(telemetry))
    {
        telemetryParameterSetup.TelemetryConfiguration = telemetry.getConfigurationContainer();
    }
}

/// <summary>
/// Handles the click event for reinitializing triggered telemetry parameter setups.
/// </summary>
/// <param name="sender">The sender of the event.</param>
/// <param name="e">Event arguments associated with the event.</param>
[
    SuppressBPWarning('BPParameterNotUsed', 'Parameter required by the event interface.'),
    FormControlEventHandler(
        formControlStr(SysIntParameters, ISMTriggeredTelemetryReinitializeParameterSetups), 
        FormControlEventType::Clicked)
]
public static void ISMTriggeredTelemetryReinitializeParameterSetups_OnClicked(
    FormControl sender, FormControlEventArgs e)
{
    ISMTelemetryParameterSetup::reinitializeParameterSetups(ISMTelemetryMode::Triggered);
    sender.formRun().dataSource(
        formDataSourceStr(SysIntParameters, ISMTelemetryParameterSetupTriggerable)).research();
}

/// <summary>
/// Handles the click event for reinitializing batchable telemetry parameter setups.
/// </summary>
/// <param name="sender">The sender of the event.</param>
/// <param name="e">Event arguments associated with the event.</param>
[
    SuppressBPWarning('BPParameterNotUsed', 'Parameter required by the event interface.'),
    FormControlEventHandler(
        formControlStr(SysIntParameters, ISMBatchableTelemetryReinitializeParameterSetups),
        FormControlEventType::Clicked)
]
public static void ISMBatchableTelemetryReinitializeParameterSetups_OnClicked(
    FormControl sender, FormControlEventArgs e)
{
    ISMTelemetryParameterSetup::reinitializeParameterSetups(ISMTelemetryMode::Batchable);
    sender.formRun().dataSource(
        formDataSourceStr(SysIntParameters, ISMTelemetryParameterSetupBatchable)).research();
}

/// <summary>
/// Filter to the AllServers status.
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[
    FormDataSourceEventHandler(
        formDataSourceStr(SysIntParameters, ISMBatchableTelemetryStatusTable), 
        FormDataSourceEventType::Initialized)
 ]
public static void ISMBatchableTelemetryStatusTable_OnInitialized(
    FormDataSource sender, FormDataSourceEventArgs e)
{
    sender.queryBuildDataSource()
        .addRange(fieldNum(ISMBatchableTelemetryStatusTable, ServerId))
        .value(ISMBatchableTelemetryConstants::AllServers);
}
